import copyreg
from test.pickletester import ExtensionSaver

def _t():
    mod, func, code = ('junk1 ', ' junk2', 43981)
    e = ExtensionSaver(code)
    try:
        try:
            copyreg.remove_extension(*(mod, func, code))
        except ValueError:
            pass
        copyreg.add_extension(mod, func, code)
        assert copyreg._extension_registry[mod, func] == code, ('assertTrue', copyreg._extension_registry[mod, func] == code)
        assert copyreg._inverted_registry[code] == (mod, func), ('assertTrue', copyreg._inverted_registry[code] == (mod, func))
        assert code not in copyreg._extension_cache, ('assertNotIn', code, copyreg._extension_cache)
        copyreg.add_extension(mod, func, code)
        try:
            copyreg.add_extension(*(mod, func, code + 1))
        except ValueError:
            pass
        try:
            copyreg.remove_extension(*(mod, func, code + 1))
        except ValueError:
            pass
        try:
            copyreg.add_extension(*(mod[1:], func, code))
        except ValueError:
            pass
        try:
            copyreg.remove_extension(*(mod[1:], func, code))
        except ValueError:
            pass
        try:
            copyreg.add_extension(*(mod, func[1:], code))
        except ValueError:
            pass
        try:
            copyreg.remove_extension(*(mod, func[1:], code))
        except ValueError:
            pass
        if code + 1 not in copyreg._inverted_registry:
            try:
                copyreg.remove_extension(*(mod[1:], func[1:], code + 1))
            except ValueError:
                pass
    finally:
        e.restore()
    assert (mod, func) not in copyreg._extension_registry, ('assertNotIn', (mod, func), copyreg._extension_registry)
    for code in (1, 2147483647):
        e = ExtensionSaver(code)
        try:
            copyreg.add_extension(mod, func, code)
            copyreg.remove_extension(mod, func, code)
        finally:
            e.restore()
    for code in (-1, 0, 2147483648):
        try:
            copyreg.add_extension(*(mod, func, code))
        except ValueError:
            pass
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
